<?php require_once 'layout.php'; require_auth(); if(is_admin()) redirect(BASE_URL.'/admin.php');$uid=$_SESSION['user_id'];
if($_SERVER['REQUEST_METHOD']==='POST'){
 if(isset($_POST['add_address'])){$phone=preg_replace('/\D/','',$_POST['phone']??''); if(strlen($phone)!==10) flash('Telefon 10 haneli olmalı.'); else {db()->prepare('INSERT INTO addresses(user_id,title,fullname,phone,province,district,neighborhood,address) VALUES(?,?,?,?,?,?,?,?)')->execute([$uid,$_POST['title'],$_POST['fullname'],$phone,$_POST['province'],$_POST['district'],$_POST['neighborhood']??'',$_POST['address']]); flash('Adres kaydedildi.');} redirect(BASE_URL.'/profile.php#addresses');}
 if(isset($_POST['add_card'])){$card=preg_replace('/\D/','',$_POST['card_number']??'');$cvv=preg_replace('/\D/','',$_POST['cvv']??''); if(strlen($card)!==16||strlen($cvv)!==3) flash('Kart 16 hane, CVV 3 hane olmalı.'); else {db()->prepare('INSERT INTO cards(user_id,card_name,card_last4,expiry) VALUES(?,?,?,?)')->execute([$uid,$_POST['card_name'],substr($card,-4),$_POST['expiry']]); flash('Kart kaydedildi.');} redirect(BASE_URL.'/profile.php#cards');}
}
if(isset($_GET['deladdr'])){db()->prepare('DELETE FROM addresses WHERE id=? AND user_id=?')->execute([(int)$_GET['deladdr'],$uid]);redirect(BASE_URL.'/profile.php#addresses');}
if(isset($_GET['delcard'])){db()->prepare('DELETE FROM cards WHERE id=? AND user_id=?')->execute([(int)$_GET['delcard'],$uid]);redirect(BASE_URL.'/profile.php#cards');}
$u=current_user();$orders=db()->prepare('SELECT * FROM orders WHERE user_id=? ORDER BY id DESC');$orders->execute([$uid]);$orders=$orders->fetchAll();$addresses=db()->prepare('SELECT * FROM addresses WHERE user_id=? ORDER BY id DESC');$addresses->execute([$uid]);$addresses=$addresses->fetchAll();$cards=db()->prepare('SELECT * FROM cards WHERE user_id=? ORDER BY id DESC');$cards->execute([$uid]);$cards=$cards->fetchAll(); page_header(t('Profilim','My Profile')); ?>
<h1 class="page-title"><?=t('Profilim','My Profile')?></h1><div class="profile-grid"><aside class="side card profile-card"><div class="avatar"><?=h(mb_strtoupper(mb_substr($u['name'],0,1)))?></div><b><?=h($u['name'])?></b><p class="muted small"><?=h($u['email'])?></p><a href="#orders">📦 <?=t('Geçmiş Siparişlerim','Order History')?></a><a href="#addresses">📍 <?=t('Kayıtlı Adreslerim','Saved Addresses')?></a><a href="#cards">💳 <?=t('Kayıtlı Kartlarım','Saved Cards')?></a></aside><section class="profile-main"><div id="orders" class="card spacious"><h2>📦 <?=t('Geçmiş Siparişlerim','Order History')?></h2><?php if(!$orders): ?><p class="muted">Henüz siparişin yok. Beğendiğin ürünleri keşfetmeye başlayabilirsin.</p><?php endif; ?><?php foreach($orders as $o): ?><div class="soft-item"><b>Sipariş #<?=$o['id']?></b> · <?=money_try($o['total'])?><?php if(!empty($o['currency'])&&$o['currency']!=='TRY'): ?> / <?=h($o['currency'])?> <?=number_format((float)$o['converted_total'],2,'.',',')?><?php endif; ?> · <?=h($o['status'])?><p><?=h($o['province'].' / '.$o['district'].' / '.($o['neighborhood']??'').' - '.$o['address'])?></p><?php $it=db()->prepare('SELECT * FROM order_items WHERE order_id=?');$it->execute([$o['id']]);foreach($it->fetchAll() as $x): ?><p>• <?=h($x['product_name'])?> x<?=$x['quantity']?> - <?=money_try($x['price'])?></p><?php endforeach; ?></div><?php endforeach; ?></div>
<div id="addresses" class="card spacious"><h2>📍 <?=t('Kayıtlı Adreslerim','Saved Addresses')?></h2><?php foreach($addresses as $a): ?><div class="soft-item"><b><?=h($a['title'])?></b><p><?=h($a['fullname'])?> · <?=h($a['phone'])?></p><p><?=h($a['province'].' / '.$a['district'].' / '.($a['neighborhood']??'').' - '.$a['address'])?></p><a class="btn danger" href="?deladdr=<?=$a['id']?>">Sil</a></div><?php endforeach; ?><h3>Yeni Adres Ekle</h3><form method="post" class="nice-form"><div class="row"><input name="title" placeholder="Adres başlığı" required><input name="fullname" placeholder="Ad Soyad" required></div><input name="phone" placeholder="Telefon 10 hane" oninput="onlyDigits(this,10)" maxlength="10" minlength="10" inputmode="numeric" required><div class="row"><select class="province" data-district="#pdistrict" data-neighborhood="#pneighborhood" name="province" onchange="updateDistrict(this)" required></select><select id="pdistrict" name="district" onchange="updateNeighborhood(this)" required></select></div><select id="pneighborhood" name="neighborhood" required></select><textarea name="address" placeholder="Açık adres" required></textarea><button class="btn primary" name="add_address">Adres Ekle</button></form></div>
<div id="cards" class="card spacious"><h2>💳 <?=t('Kayıtlı Kartlarım','Saved Cards')?></h2><p class="muted">Kart numarası ve CVV ödeme sırasında doğrulanır; güvenlik için sadece son 4 hane kaydedilir.</p><?php foreach($cards as $c): ?><div class="soft-item"><b><?=h($c['card_name'])?></b><p>**** **** **** <?=h($c['card_last4'])?> · <?=h($c['expiry'])?></p><a class="btn danger" href="?delcard=<?=$c['id']?>">Sil</a></div><?php endforeach; ?><h3>Yeni Kart Ekle</h3><form method="post" class="nice-form"><input name="card_name" placeholder="Kart üzerindeki isim" required><input name="card_number" placeholder="Kart numarası 16 hane" oninput="onlyDigits(this,16)" maxlength="16" minlength="16" inputmode="numeric" required><div class="row"><input name="expiry" placeholder="AA/YY" maxlength="5" pattern="(0[1-9]|1[0-2])/\d{2}" required><input name="cvv" placeholder="CVV 3 hane" oninput="onlyDigits(this,3)" maxlength="3" minlength="3" inputmode="numeric" required></div><button class="btn primary" name="add_card">Kart Ekle</button></form></div></section></div>
<?php page_footer(); ?>
